-- Reconciliations cell (reconciliations), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA reconciliations;

CREATE FUNCTION reconciliations.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE reconciliations.reconciliations (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    account_id               bigint,
    period_start             date NOT NULL,
    period_end               date NOT NULL,
    source_type              text NOT NULL CHECK (source_type IN ('bank_statement', 'wallet_export', 'invoice_register', 'manual', 'other')),
    source_ref               text,
    expected_amount          double precision,
    reconciled_amount        double precision,
    difference_amount        double precision,
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    status                   text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'matched', 'exception', 'closed')),
    reconciled_at            timestamptz,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX reconciliations_legacy ON reconciliations.reconciliations (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX reconciliations_account_id ON reconciliations.reconciliations (workspace_id, account_id);
CREATE INDEX reconciliations_source_type ON reconciliations.reconciliations (workspace_id, source_type);
CREATE INDEX reconciliations_status ON reconciliations.reconciliations (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE reconciliations.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('reconciliation')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE reconciliations.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON reconciliations.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['reconciliations', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE reconciliations.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE reconciliations.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON reconciliations.%I'
                       ' USING (workspace_id = reconciliations.current_workspace())'
                       ' WITH CHECK (workspace_id = reconciliations.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA reconciliations TO reconciliations_api;
GRANT EXECUTE ON FUNCTION reconciliations.current_workspace() TO reconciliations_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON reconciliations.reconciliations TO reconciliations_api;
GRANT USAGE ON SEQUENCE reconciliations.reconciliations_id_seq TO reconciliations_api;
GRANT SELECT, INSERT ON reconciliations.create_keys TO reconciliations_api;
GRANT SELECT, INSERT ON reconciliations.outbox TO reconciliations_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON reconciliations.outbox TO reconciliations_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON reconciliations.outbox TO reconciliations_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA reconciliations TO reconciliations_publisher;
GRANT SELECT ON reconciliations.outbox TO reconciliations_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON reconciliations.outbox TO reconciliations_publisher;
